def longestRepeatingSubstring(S):
    n = len(S)

    # Helper to check if any substring of length L repeats
    def search(L):
        seen = set()
        for i in range(n - L + 1):
            substring = S[i:i+L]
            if substring in seen:
                return True
            seen.add(substring)
        return False

    left, right = 1, n
    answer = 0
    while left <= right:
        mid = left + (right - left) // 2
        if search(mid):
            answer = mid    # substring of length mid repeats, try longer
            left = mid + 1
        else:
            right = mid - 1
    return answer
